import { buildBoxPlotLayout } from '@dreadnought/core';
const layout = buildBoxPlotLayout({data:[{id:'a',label:'A',values:[1,2,3,4,5,6,7,100]}]});
const median = layout.groups[0].summary?.median;

import { buildHistogram } from '@dreadnought/core';
const result = buildHistogram({ data: [0, 1, 2, 3, 4], bins: 2, domain: [0, 4] });
const intervals = result.bins;

import { buildHeatmapLayout } from '@dreadnought/core';
const layout = buildHeatmapLayout({ columns: [{ id: 'mon', label: 'Пн' }], rows: [{ id: 'team', label: 'Команда' }], data: [{ row: 'team', column: 'mon', value: 10 }] });
const cells = layout.cells;

import { buildScatterLayout } from '@dreadnought/core';
const series = [{ id: 'a', label: 'Кампании', data: [{ id: 'one', label: 'Поиск', x: 20, y: 40, size: 100 }, { id: 'two', label: 'Соцсети', x: 40, y: 60, size: 200 }] }];
const layout = buildScatterLayout({series, xDomain:[0,100], yDomain:[0,100], width:500, height:300});

import { buildPieLayout } from '@dreadnought/core';
const layout = buildPieLayout({data:[{id:'a',label:'A',value:30},{id:'b',label:'B',value:70}],radius:100,innerRadius:0.6});
const slices = layout.slices;

import { buildLineLayout, sampleLineLayout } from '@dreadnought/core';
const source = buildLineLayout({series:[{id:'a',label:'A',data:[{x:0,y:20},{x:5,y:60},{x:10,y:40}]}],xDomain:[0,10],yDomain:[0,100],width:1,height:1});
const view = sampleLineLayout(source,500,300,[0,10]);

import { buildLineLayout, getLinePointAtX } from '@dreadnought/core';
const source = buildLineLayout({series:[{id:'a',label:'A',data:[{x:0,y:20},{x:10,y:40}]}],xDomain:[0,10],yDomain:[0,100],width:1,height:1});
const point = getLinePointAtX(source.series[0].segments.flat(),7);

import { buildBarLayout } from '@dreadnought/core';
const layout = buildBarLayout({categories:[{id:'one',label:'One'}],series:[{id:'a',label:'A',values:{one:-10}}],domain:[-20,40],width:500,height:300});
const baseline = layout.baseline;

import { buildLineLayout, getClosestLinePoint } from '@dreadnought/core';
const layout = buildLineLayout({series:[{id:'a',label:'A',data:[{x:0,y:20},{x:5,y:60},{x:10,y:40}]}],xDomain:[0,10],yDomain:[0,100],width:500,height:300});
const closest = getClosestLinePoint(layout,250,120);

import { buildLineLayout, getClosestLinePoint } from '@dreadnought/core';
